import java.util.*;
public class CF1342E {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long k = sc.nextLong();
        final int MOD = 998244353;
        if (k >= n) {
            System.out.println(0);
            return;
        }
        int c = n - (int) k;
        long[] fact = new long[2 * n];
        long[] invFact = new long[2 * n];
        fact[0] = 1;
        for (int i = 1; i < 2 * n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        invFact[2 * n - 1] = modInverse(fact[2 * n - 1], MOD);
        for (int i = 2 * n - 2; i >= 0; i--) {
            invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
        }
        long total = 0;
        for (int a = 1; a <= c; a++) {
            long val = (power(a, n, MOD) * nCr(c, a, fact, invFact, MOD)) % MOD;
            total += (a % 2 == 0 ? 1 : -1) * val;
        }
        total = ((total % MOD) + MOD) % MOD;
        total = (total * nCr(n, c, fact, invFact, MOD)) % MOD;
        if (k > 0) total = (total * 2) % MOD;
        System.out.println(total);
    }

    static long power(long base, int exp, int mod) {
        long res = 1;
        long cur = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * cur) % mod;
            cur = (cur * cur) % mod;
            exp >>= 1;
        }
        return res;
    }

    static long nCr(int n, int r, long[] fact, long[] invFact, int mod) {
        return fact[n] * invFact[r] % mod * invFact[n - r] % mod;
    }

    static long modInverse(long a, int m) {
        return power(a, m - 2, m);
    }
}
